using Microsoft.AspNetCore.Mvc; using Exercicio11_Notas.Models; namespace Exercicio11_Notas.Controllers; public class AlunoController:Controller{private static readonly List<Aluno> Dados=new(){new(){Id=1,Nome="Aluno 1",Curso="DS",Nota1=1,Nota2=3,Nota3=5},new(){Id=2,Nome="Aluno 2",Curso="DS",Nota1=2,Nota2=4,Nota3=6},new(){Id=3,Nome="Aluno 3",Curso="DS",Nota1=3,Nota2=5,Nota3=7},new(){Id=4,Nome="Aluno 4",Curso="DS",Nota1=4,Nota2=6,Nota3=8},new(){Id=5,Nome="Aluno 5",Curso="DS",Nota1=5,Nota2=7,Nota3=9},new(){Id=6,Nome="Aluno 6",Curso="DS",Nota1=6,Nota2=8,Nota3=0},new(){Id=7,Nome="Aluno 7",Curso="DS",Nota1=7,Nota2=9,Nota3=1},new(){Id=8,Nome="Aluno 8",Curso="DS",Nota1=8,Nota2=0,Nota3=2},new(){Id=9,Nome="Aluno 9",Curso="DS",Nota1=9,Nota2=1,Nota3=3},new(){Id=10,Nome="Aluno 10",Curso="DS",Nota1=0,Nota2=2,Nota3=4},}public IActionResult Index()=>View(Dados); public IActionResult Aprovados()=>View("Index",Dados.Where(x=>x.Media>=6)); public IActionResult Recuperacao()=>View("Index",Dados.Where(x=>x.Media>=4&&x.Media<6)); public IActionResult Reprovados()=>View("Index",Dados.Where(x=>x.Media<4));}
